"""Final raw evidence replay, integrity and scientific plots; no new search."""
import argparse,sqlite3,json,statistics
from collections import Counter
from common import *
from oracle import validate_result,validate_spec

def run(out):
    out.mkdir(parents=True,exist_ok=False);compiler=read(HERE/'outputs/COMPILER_FINAL/COMPILER_ACCEPTANCE.json');bridge=read(HERE/'outputs/BRIDGE_FINAL/BRIDGE_ACCEPTANCE.json');supp=read(HERE/'outputs/SUPPLEMENTAL_FINAL/SUPPLEMENTAL_ACCEPTANCE.json')
    tests=[];records=[];baseline=[]
    def check(name,ok,details=None):tests.append(dict(name=name,passed=bool(ok),details=details))
    check('FINAL_COMPILER_GATE',compiler['passed']);check('FINAL_BRIDGE_GATE',bridge['passed']);check('FINAL_SUPPLEMENTAL_GATE',supp['passed'])
    for e in read(HERE/'outputs/COMPILER_FINAL/CASE_ORACLE_EXPECTATIONS.json'):
        dest=HERE/'outputs/COMPILER_FINAL'/e['name'];req=read(dest/'REQUEST.json');spec=read(dest/'SPEC.json');policy=read(dest/'POLICY.json');v=validate_spec(req,spec,policy,e['expected_status'],e['expected_counts']);check('SPEC_REPLAY_'+e['name'],v['valid'],v['errors'])
        b=read(dest/'BASELINE_SPEC.json');baseline.append(dict(case=e['name'],status=spec['status'],quantities=spec['required_quantities'],equivalent=digest({k:v for k,v in spec.items() if k not in ['method','spec_sha256']})==digest({k:v for k,v in b.items() if k not in ['method','spec_sha256']})))
    paths=list((HERE/'outputs/BRIDGE_FINAL').glob('*/RESULT.json'))+list((HERE/'outputs/SUPPLEMENTAL_FINAL').glob('*/RESULT.json'))+[HERE/'outputs/DEMO_FINAL/execution/RESULT.json']
    for path in paths:
        folder=path.parent;req=read(folder/'REQUEST.json');spec=read(folder/'SPEC.json');response=read(path);v=validate_result(req,spec,response);check('RESULT_REPLAY_'+str(folder.relative_to(HERE)),v['valid'],v['errors'])
        records.append(dict(path=str(path.relative_to(HERE)),status=response['status'],reason=response['reason'],evaluations=response['optimizer_evaluations'],optimizer_calls=response['optimizer_calls'],candidate_count=len(response['candidate_layouts']),menu_count=len(response['selected_ids']),independent=v))
        with sqlite3.connect(folder/'scene.sqlite3') as c:row=c.execute('SELECT request,spec,response,sha FROM results WHERE run_id=?',(response['run_id'],)).fetchone()
        check('SQLITE_'+str(folder.relative_to(HERE)),digest(json.loads(row[0]))==digest(req) and digest(json.loads(row[1]))==digest(spec) and digest(json.loads(row[2]))==row[3]==digest(response))
    check('BASELINE_ALL_CASES_EQUIVALENT',all(r['equivalent'] for r in baseline),dict(cases=len(baseline)))
    before=read(HERE/'outputs/COMPILER_FINAL/PRESERVATION_BEFORE.json');now=immutable_snapshot();missing=[p for p in before if p not in now];drift=[p for p in before if p in now and before[p]!=now[p]];check('FROZEN_AND_PRIOR_EVIDENCE_UNCHANGED',not missing and not drift,dict(files=len(before),missing=missing,changed=drift));save(out/'PRESERVATION_AFTER.json',now)
    save(out/'RAW_REPLAY.json',records);save(out/'STRONG_BASELINE_COMPARISON.json',baseline)
    success=[r for r in records if r['status']=='success'];summary=dict(status='VALIDATED_CONTROLLED_EVENT_SCENE_POC' if all(t['passed'] for t in tests) else 'FAILED',compiler_case_instances=compiler['case_count'],compiler_assertions=len(compiler['results']),compiler_passed=sum(r['passed'] for r in compiler['results']),bridge_assertions=len(bridge['checks']),bridge_passed=sum(r['passed'] for r in bridge['checks']),supplemental_assertions=len(supp['checks']),supplemental_passed=sum(r['passed'] for r in supp['checks']),closeout_assertions=len(tests),closeout_passed=sum(t['passed'] for t in tests),baseline_equivalent_cases=len(baseline),baseline_actual_matched_search=True,success_result_records=len(success),validated_layout_records=sum(r['candidate_count'] for r in success),menu_counts=[dict(path=r['path'],count=r['menu_count']) for r in success],preserved_files=len(before),new_algorithmic_novelty_established=False,all_scenarios_synthetic=True,research_scope='Event-agnostic finite-profile specification logic; Wedding-only supported initial seating optimization with explicitly pinned equipment and reserved zones',tests=tests)
    save(out/'FUNCTIONAL_ACCEPTANCE.json',summary)
    # Actual selected metric polygons, with zones separate from physical objects.
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from matplotlib.patches import Polygon as Patch
    folder=HERE/'outputs/DEMO_FINAL/execution';response=read(folder/'RESULT.json');spec=read(folder/'SPEC.json');req=read(folder/'REQUEST.json')
    selected=[l for lid in response['selected_ids'] for l in response['candidate_layouts'] if l['layout_id']==lid];fig,axes=plt.subplots(1,len(selected),figsize=(6*len(selected),6),squeeze=False)
    for ax,l in zip(axes[0],selected):
        x,y=zip(*req['venue']['boundary_m']);ax.plot(x,y,color='black')
        for o in l['objects']:
            existing=o['object_id'] in {x['instance_id'] for x in spec['retained_existing']};color='#59616c' if existing else '#a24a23' if o['class'] in ['stage','buffet_counter'] else '#43828a';ax.add_patch(Patch(o['footprint_coordinates_m'],facecolor=color,alpha=.8,linewidth=.3,edgecolor='white'))
        for z in l['zones']:
            if z['exclusive']:ax.add_patch(Patch(z['footprint_m'],fill=False,hatch='///',edgecolor='#704b74',linewidth=1))
        m=l['objective_metrics'];ax.set_title(f'{l["layout_id"]}\nstage {m["mean_stage_distance_m"]:.3f} m; initializer move {m["initializer_assignment_movement_m"]:.3f} m');ax.set_aspect('equal');ax.set_xlabel('x (m)');ax.set_ylabel('y (m)');ax.autoscale_view()
    fig.suptitle('ACTUAL controlled empty-hall outputs: new stage/buffets pinned by simulated design inputs; hatched zones remain clear',fontsize=12);fig.tight_layout();fig.savefig(out/'ACTUAL_THREE_LAYOUTS.png',dpi=160);plt.close(fig)
    # Exact methods/evidence scope, not new high-level research definition.
    lines=['# Event Scene Intelligence V1 — functional acceptance','',f'**{summary["status"]}**. Compiler: {summary["compiler_passed"]}/{summary["compiler_assertions"]}; bridge: {summary["bridge_passed"]}/{summary["bridge_assertions"]}; supplemental: {summary["supplemental_passed"]}/{summary["supplemental_assertions"]}; raw closeout: {summary["closeout_passed"]}/{summary["closeout_assertions"]}. These are assertion groups, not independent real events.','',f'{summary["compiler_case_instances"]} specification cases compare the reusable policy interpreter to a conventional count/assignment strategy. All semantic specifications match. Both share structural/evidence/geometry gates and output representation; the separate oracle does not import the compiler, baseline or those gates. Default expected counts/statuses are explicit test fixtures; oracle uses separate finite-function equations. This tests correctness and finds no superiority/novelty.','',f'One actual matched baseline search returns identical normalized polygons. Six representative Wedding scenarios use the unchanged frozen initial engine: empty, partial, dance, 120 guests, permitted excess removal and stricter hard bounds. Additional actual CLI/offline demonstrations are repeats, not extra independent scenario coverage. {summary["validated_layout_records"]} raw candidate records across {summary["success_result_records"]} successful saved results were independently replayed, including correlated repeats.','', '## Implemented','', 'Strict two-actor/profile approval binding; source and decision evidence hashes; independent metric calibration; explicit activity/count/zone rules; compatible reviewed stock reuse; distinct new supply; locked retained geometry; authorized excess removal; pending/conflict/unsupported reports; actual constrained seating search; separate reservations versus physical objects; actual Pareto candidates and material-diversity menu; numerical/rule XAI and isolated SQLite readback.','', '## Actual failures and limits','', 'An actual 1200-evaluation search under an unsatisfied hard stage limit returned no candidates and did not claim global infeasibility. Non-Wedding optimizer calls and non-eight-divisible capacities are rejected before search. One/two/duplicate-pool menu probes never manufacture three. Unknown hard/context inputs, unreviewed/uncertain stock, missing/foreign evidence and wrong authority are rejected or held.','', 'Seven event names map to four configurable specification profiles. Only Wedding eight-seat initial layout search is supported. Other profiles produce specifications, not validated layouts. Existing loose table/chair regrouping and relocation are unsupported. Fixed and protected stock remains unchanged; movable reuse is in place. No automatic placement optimization of stage/buffet/zones: simulated planner design controls pin new equipment; profile rules derive access reservations. Broad activity membership regions are not detailed circulation, sightline, acoustic, performance or crowd-flow validation.','', 'The old public reviewed-Twin API still requires an existing stage. This module introduces an explicit isolated observed-metric-scene contract and calls the unchanged low-level engine; it does not register fake detected stages, modify the frozen backend or claim the existing HTTP workflow accepts these inputs. Source-to-module model-candidate ingestion and real-venue review are not integrated here. All generated source images/review/role/permission records are explicitly synthetic fixtures.','', 'Accepted specification means a complete declared-scope design program, not physical supply availability or successful geometry. New equipment is a supply/design requirement, not a detected object. The bridge independently verifies actual output before success. Source/version hashes bind snapshots; this module has no multi-user latest-version registry, authenticated identity, concurrent revocation protocol or production access control.','', 'S-GCN, weather, detailed safety, general multi-event optimization, planner feedback learning and adaptive integration with this new scene contract remain unfinished original A–F objectives. Basic experimental geometry constraints are not safety certification. Initial displacement is to the seeded initializer, not real transport cost. No human explanation benefit or new NSGA-II is claimed.','', '## Preserved failed runs/corrections','', 'FAILED_IMPORT_001.json preserves the initial module-resolution failure. COMPILER_RELEASE_001 records a failed equivalence assertion for duplicate existing IDs: both methods rejected, but tentative invalid allocations differed; rejected input now emits no allocation. Review metadata and document-source evidence binding were strengthened; actor approval now binds policy hash. An emitted conference-zone name was corrected to its configured policy name and independent name/geometry checks added. Earlier draft schemas/examples are retained, not current inputs. SUPPLEMENTAL_RELEASE_001 records an overbroad socket guard failing on local gethostname; corrected guard distinguishes local hostname reads from DNS/connect/send/bind attempts. Final offline runtime succeeds with zero denied network events; this is Python-level instrumentation, not OS/native traffic certification.','',f'Preservation: {len(before)} targeted original/runtime/checkpoint/frontend/prior-evidence files unchanged. This is not a fresh bytewise audit of every raw dataset file. Actual commands and raw errors remain in the output folders/logs.','']
    with (out/'FUNCTIONAL_ACCEPTANCE.md').open('x',encoding='utf-8') as f:f.write('\n'.join(lines))
    print(json.dumps({k:v for k,v in summary.items() if k not in ['tests','menu_counts']},indent=2))
    if summary['status']=='FAILED':raise SystemExit(1)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--out',default='outputs/CLOSEOUT_FINAL');a=p.parse_args();out=(HERE/a.out).resolve()
    if not out.is_relative_to(HERE):raise ValueError('ISOLATION')
    run(out)
